function modelIcon(name){const n=name.toLowerCase();const k=n.includes('deepseek')?'deepseek':n.includes('qwen')?'qwen':n.includes('kimi')||n.includes('moonshot')?'kimi':n.includes('claude')?'anthropic':n.includes('gemini')?'gemini':n.includes('gpt')||n.startsWith('o3')||n.startsWith('o4')?'openai':n.includes('mistral')?'mistral':n.includes('grok')?'xai':null;return k?providerLogo(k):'';}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;if(el.closest('form')&&el.type!=='submit')e.preventDefault();Promise.resolve(handle(el.dataset.action,el)).catch(error=>{const box=$('#form-error');if(box)box.textContent=error.message;else toast(error.message);});});
document.addEventListener('input',e=>{if(e.target.id==='prompt')draft=e.target.value;if(e.target.id==='app-search')filterApps(e.target.value);});
document.addEventListener('change',e=>{(async()=>{if(e.target.dataset.setting){const k=e.target.dataset.setting;settings[k]=k==='theme'?(e.target.checked?'dark':'light'):e.target.checked;theme();await save();}if(e.target.id==='max-steps'){settings.maxSteps=Number(e.target.value);await save();}})().catch(e=>toast(e.message));});
document.addEventListener('submit',e=>{if(e.target.id!=='editor')return;e.preventDefault();(async()=>{const f=e.target,data=formData(),kind=f.dataset.kind;data.id=f.dataset.id;
 if(!['reasoning','limits','appearance','appPolicy'].includes(kind)&&!data.name?.trim())throw Error('Введите название');
 if(kind==='appPolicy'){for(const key of ['allowedApps','blockedApps']){const values=data[key].split(/\s+/).filter(Boolean);if(values.length>200||values.some(x=>!/^[a-zA-Z0-9_.]+$/.test(x)))throw Error('Укажите package ID, по одному на строку (до 200)');settings[key]=values;}}
 if(kind==='appearance'){if(data.accent&&!/^#[0-9a-f]{6}$/i.test(data.accent))throw Error('Акцент: #3B5BDB или пустое поле');Object.assign(settings,{accent:data.accent,fontSize:Number(data.fontSize),density:data.density,amoled:f.querySelector('[name=amoled]').checked,materialYou:f.querySelector('[name=materialYou]').checked});}
 if(kind==='prompt'){if(!data.text.trim())throw Error('Добавьте текст');settings.prompts=settings.prompts||[];settings.prompts.push({id:data.id,name:data.name,text:data.text});}
 if(kind==='role'){const tools=data.tools.split(',').map(t=>t.trim()).filter(Boolean);const role={id:data.id,name:data.name,prompt:data.prompt,tools,modelProfile:data.modelProfile,effort:data.effort,trust:data.trust,readOnly:f.querySelector('[name=readOnly]').checked};settings.roles=settings.roles||[];const i=settings.roles.findIndex(r=>r.id===role.id);if(i<0)settings.roles.push(role);else settings.roles[i]=role;}
 if(kind==='limits'){const sec=Number(data.maxSeconds),tokens=Number(data.maxTokens);if(sec<10||sec>3600||tokens<1024||tokens>500000)throw Error('Время: 10–3600 с, токены: 1024–500000');Object.assign(settings,{maxSeconds:sec,maxTokens:tokens,doubleCheck:f.querySelector('[name=doubleCheck]').checked,teamMode:f.querySelector('[name=teamMode]').checked});}
 if(kind==='profile'){data.freeOnly=f.dataset.free==='true';if(!data.base.startsWith('https://'))throw Error('Адрес API должен начинаться с https://');if(!data.model.trim())throw Error('Укажите имя модели');data.preset=f.dataset.preset;const i=settings.profiles.findIndex(p=>p.id===data.id);if(i<0)settings.profiles.push(data);else settings.profiles[i]=data;if(!settings.activeProfile)settings.activeProfile=data.id;}
 if(kind==='reasoning'){const p=settings.profiles.find(p=>p.id===data.id);if(!p)throw Error('Подключение не найдено');p.thinking=data.thinking;p.effort=data.effort;}
 if(kind==='service'){if(!data.url.startsWith('https://'))throw Error('Укажите HTTPS-адрес');data.enabled=f.querySelector('[name=enabled]').checked;data.preset=f.dataset.preset;const i=settings.services.findIndex(s=>s.id===data.id);if(i<0)settings.services.push(data);else settings.services[i]=data;}
 if(kind==='skill'){if(!data.content.trim())throw Error('Добавьте инструкции');if(data.content.length>100000)throw Error('Навык слишком большой: максимум 100 000 символов');data.enabled=f.querySelector('[name=enabled]').checked;const i=settings.skills.findIndex(s=>s.id===data.id);if(i<0)settings.skills.push(data);else settings.skills[i]=data;}
 await save();closeModal();render();toast('Сохранено');})().catch(e=>{if($('#form-error'))$('#form-error').textContent=e.message;else toast(e.message);});});
window.goBack=()=>{if($('#modal-root').innerHTML){closeModal();return;}if(page!=='chat'||viewingHistory){page='chat';viewingHistory=false;native('state').then(s=>{run=s.run;render();});return;}if(!run.running&&run.task){native('newChat').then(()=>{run={};render();});}};
function accessibilityHelp(){
 modal('Управление телефоном',`<p class="subhead">${esc(device.message||(accessibility?'Служба W Agent подключена.':'Разрешение включается в настройках Android.'))}</p>${device.enabled&&!accessibility?'<p class="note">Если Android пишет «Сервис работает некорректно», выключите W Agent в списке служб, затем снова включите и вернитесь сюда. После обновления APK Android иногда требует повторного включения.</p>':''}<div class="actions">${button('deviceTest','Проверить связь')}${button('reconnect','Переподключить')}</div><div class="setup-steps"><div><span>1</span><p>Откройте карточку W Agent в настройках телефона.</p></div><div><span>2</span><p>Если Android пишет «В целях безопасности», откройте меню <strong>⋮</strong> и выберите <strong>«Разрешить ограниченные настройки»</strong>. Подтвердите действие способом разблокировки телефона.</p></div><div><span>3</span><p>Откройте специальные возможности → скачанные приложения или службы → <strong>W Agent</strong> и включите службу.</p></div></div><div class="actions">${button('appSettings','Карточка W Agent')}${button('openAccessibility','Включить службу','primary')}</div><details class="help-details"><summary>Для POCO / Xiaomi</summary><p>В карточке W Agent откройте «Контроль активности» или «Экономия батареи» и выберите «Нет ограничений». Разрешите фоновый автозапуск, если этот пункт есть. После этого выключите и включите службу W Agent в специальных возможностях. Названия зависят от версии MIUI / HyperOS.</p>${device.lastError?'<p>Последняя ошибка: '+esc(device.lastError)+'</p>':''}</details><details class="help-details"><summary>Нет нужного пункта?</summary><p>Названия меню зависят от Android и производителя. На телефоне с рабочим профилем, родительским контролем или политикой организации доступ может ограничивать администратор. В этом случае обратитесь к владельцу политики устройства.</p><p>Служба видит открытый экран и может нажимать элементы. Во время запущенной задачи данные отправляются выбранной модели. Задача останавливается кнопкой W или через уведомление.</p></details>`);
}
function effortLabel(p){if(!p)return 'Авто';if(p.thinking==='off')return 'Без размышлений';return ({minimal:'Minimal',low:'Low',medium:'Medium',high:'High',xhigh:'Extreme',max:'Max'})[p.effort]||(p.thinking==='on'?'Размышления':'Авто');}
function reasoningFields(p){
 const gemini=p.type==='gemini'&&!p.model?.startsWith('gemini-2');
 const levels=gemini?[['auto','Авто'],['low','Low'],['high','High']]:[['auto','Авто'],['minimal','Minimal'],['low','Low'],['medium','Medium'],['high','High'],['xhigh','Extreme · xhigh'],['max','Max']];
 return `<details class="help-details reasoning-settings"><summary>Размышления · ${esc(effortLabel(p))}</summary><label class="field"><span>Режим рассуждений</span><select name="thinking"><option value="auto" ${!p.thinking||p.thinking==='auto'?'selected':''}>Авто · настройка модели</option><option value="on" ${p.thinking==='on'?'selected':''}>Включены</option>${!gemini?`<option value="off" ${p.thinking==='off'?'selected':''}>Выключены</option>`:''}</select></label><label class="field"><span>Усилие</span><select name="effort">${levels.map(([id,name])=>`<option value="${id}" ${p.effort===id?'selected':''}>${name}</option>`).join('')}</select></label><p>Поддержка зависит от модели и API. Extreme соответствует xhigh для OpenAI и OpenRouter; для Anthropic уровни задают бюджет токенов. Если модель не принимает выбранный параметр, выберите Авто. Больше рассуждений может увеличивать время ответа и расход токенов.</p></details>`;
}
function reasoningDialog(){const p=active();if(!p){profileEditor();return;}modal('Размышления',`<form id="editor" data-kind="reasoning" data-id="${esc(p.id)}"><p class="subhead">${esc(p.model)}</p>${reasoningFields(p)}<div id="form-error" class="error-text"></div><button class="primary full" type="submit">Применить</button></form>`);$('#editor details').open=true;}
