let terminalTimer;
function renderTerminal(){
 $('#main').innerHTML=title('Терминал')+`<p class="subhead">Linux внутри W Agent · без отдельного Termux</p><p id="linux-status" class="note">Проверка окружения…</p><div class="actions"><label class="field"><span>Окружение</span><select id="terminal-runtime"><option value="linux">Alpine Linux · PRoot</option><option value="android">Android · системный shell</option></select></label><label class="field"><span>Таймаут, секунд</span><input id="terminal-timeout" type="number" min="1" max="600" value="120"></label></div><div class="terminal-presets">${['pwd','ls -la','pkg update','pkg install python3 py3-pip nodejs npm git openssh build-base','python3 --version; node --version; git --version','command -v codex; command -v opencode'].map(cmd=>button('terminalPreset',esc(cmd),'secondary',`data-cmd="${esc(cmd)}"`)).join('')}</div><label class="field"><span>Папка внутри workspace</span><input id="terminal-cwd" placeholder="Корень workspace · /workspace в Linux"></label><div id="terminal-jobs"></div><label class="field mono"><span>Команда</span><textarea id="terminal-command" spellcheck="false" placeholder="echo hello"></textarea></label>${button('terminalRun','Выполнить','primary full')}<p class="note">Linux распаковывается при первом запуске. Пакеты устанавливаются из Alpine через apk или pkg; имена и доступность отличаются от Termux. Для установки нужен интернет и свободное место. Каждая команда запускается в новом shell; файлы и пакеты сохраняются. Интерактивные TUI пока не поддерживаются. PRoot не даёт root Android и не является отдельной границей безопасности. Codex/OpenCode требуют отдельной установки и проверки совместимости. Сборка APK — через GitHub Actions. Kill завершает непосредственный процесс; отделённые дочерние процессы могут пережить его.</p>`;
 native('terminalStatus').then(status=>{const el=$('#linux-status');if(el)el.textContent=status?.available?(status.installed?'Alpine 3.22.8 готов · ':'Alpine 3.22.8 включён в APK · первая распаковка при запуске · ')+status.abi:(status?.error||'Linux отсутствует в этой сборке');}).catch(e=>toast(e.message));
 clearInterval(terminalTimer);refreshTerminal().catch(e=>toast(e.message));terminalTimer=setInterval(()=>{if(page!=='terminal'){clearInterval(terminalTimer);return;}refreshTerminal().catch(()=>{});},700);
}
