function markdown(text){
 if(!window.marked||!window.DOMPurify)return esc(text);
 const renderer=new marked.Renderer();renderer.html=token=>esc(token.text||'');const raw=marked.parse(text,{breaks:true,gfm:true,renderer});
 const safe=DOMPurify.sanitize(raw,{ALLOWED_TAGS:['p','br','strong','em','del','blockquote','ul','ol','li','pre','code','h1','h2','h3','h4','hr','table','thead','tbody','tr','th','td','a'],ALLOWED_ATTR:['href','class','title']});
 const box=document.createElement('div');box.innerHTML=safe;box.querySelectorAll('a').forEach(a=>{if(a.getAttribute('href')?.startsWith('https://')){a.dataset.action='externalLink';a.dataset.url=a.getAttribute('href');}else a.removeAttribute('href');});
 box.querySelectorAll('pre code').forEach(code=>{if(window.hljs)try{hljs.highlightElement(code);}catch(e){}const b=document.createElement('button');b.className='copy-code';b.dataset.action='copyCode';b.textContent='Копировать';code.parentElement.prepend(b);});return box.innerHTML;
}
function showMenu(){modal('W Agent',`<div class="drawer-links">${[['chat','chat','Чат'],['history','clock','История'],['terminal','code','Терминал'],['files','folder','Проект и файлы'],['apps','apps','Приложения'],['connections','model','Модели и сервисы'],['skills','skills','Навыки'],['settings','settings','Настройки']].map(([p,i,n])=>`<button class="row" data-action="nav" data-page="${p}">${icon(i)}${n}</button>`).join('')}${[['schedules','clock','Расписание'],['taskQueue','clock','Очередь задач'],['macros','code','Сценарии'],['roleMenu','shield','Роли и доверие'],['promptLibrary','file','Библиотека промптов'],['usageView','model','Расход и контекст'],['memoryView','skills','Память'],['voiceStop','volume','Остановить озвучку']].map(([a,i,n])=>`<button class="row" data-action="${a}">${icon(i)}${n}</button>`).join('')}</div><p class="meta">by @wromly</p>`);$('.modal-backdrop').classList.add('drawer-backdrop');}
let backupImportText='';
function journal(){modal('Поиск в чатах и действиях',`<label class="field"><span>Поиск по тексту</span><input id="journal-search" placeholder="Задача, действие или результат"></label><div id="journal-results"></div>`);filterJournal('');}
function filterJournal(query){const q=query.toLowerCase(),hits=[];for(const h of settings.history||[])for(const e of h.events||[])if(['action','result','notice','verification','assistant'].includes(e.kind)&&(h.task+' '+e.text).toLowerCase().includes(q))hits.push({task:h.task,...e});$('#journal-results').innerHTML=hits.slice(-100).reverse().map(e=>`<details class="step-card"><summary>${esc(e.kind)} · ${esc(e.task?.slice(0,60))}</summary><pre>${esc(e.text)}</pre></details>`).join('')||'<p class="note">Совпадений нет</p>';}
document.addEventListener('input',e=>{if(e.target.id==='journal-search')filterJournal(e.target.value);});
let polling=false;
async function poll(){if(polling)return;polling=true;try{const state=await native('state');const accessChanged=accessibility!==state.accessibility||device.state!==state.device?.state;accessibility=state.accessibility;device=state.device||device;if(accessChanged){if(page==='chat'&&!viewingHistory)renderChat();if(page==='settings')renderSettings();}const next=state.run,key=JSON.stringify(next);if(!viewingHistory&&key!==lastRunKey){lastRunKey=key;if(next.task){const wasRunning=run.running;run=next;if(page==='chat'){renderChat();renderComposer();}if(wasRunning&&!run.running){await refreshHistory();if(page==='chat')renderChat();}}}}catch(e){}finally{polling=false;}}
window.receiveShared=async()=>{try{const data=await native('shared');if(data.text||data.files?.length){if(run.running){toast('Остановите задачу перед отправкой вложения');return;}draft=[draft,data.text].filter(Boolean).join('\n');files.push(...(data.files||[]));page='chat';render();}}catch(e){toast(e.message);}};
async function init(){try{const s=await native('init');settings={...settings,...s.settings};settings.skills=settings.skills||[];accessibility=s.accessibility;device=s.device||{};version=s.version||version;run=s.run;lastRunKey=JSON.stringify(run);render();window.receiveShared();setInterval(poll,700);}catch(e){$('#main').innerHTML=`<div class="empty">${icon('warning')}<h3>Не удалось открыть приложение</h3><p>${esc(e.message)}</p></div>`;}}
init();
